const _ = require('lodash');
function mergePreferences(current, input) { return _.merge({}, current, input); }

// Express body-parser uses JSON.parse. The resulting object's "__proto__" key
// is a regular own property (not the prototype link), so lodash WILL recurse into it.
const body = JSON.parse('{"__proto__":{"isAdmin":true}}');
console.log('has own __proto__?', Object.prototype.hasOwnProperty.call(body, '__proto__'));
const out = mergePreferences({}, body);
console.log('After merge, fresh {}.isAdmin?', ({}).isAdmin);
console.log('Polluted?', ({}).isAdmin === true);
